Banking.schema:
CREATE TABLE customers (customer_id INT PRIMARY KEY, customer_name VARCHAR(100), city VARCHAR(50), segment VARCHAR(30), joined_date DATE);
CREATE TABLE account_products (product_id INT PRIMARY KEY, product_name VARCHAR(100), category VARCHAR(50), status VARCHAR(30), base_value NUMERIC(14,2));
CREATE TABLE accounts (account_id INT PRIMARY KEY, customer_id INT REFERENCES customers(customer_id), product_id INT REFERENCES account_products(product_id), open_date DATE, status VARCHAR(30), balance NUMERIC(14,2));
CREATE TABLE transactions (transaction_id INT PRIMARY KEY, account_id INT REFERENCES accounts(account_id), transaction_date DATE, transaction_type VARCHAR(40), quantity INT, amount NUMERIC(14,2), status VARCHAR(30));

Healthcare.schema:
CREATE TABLE patients (patient_id INT PRIMARY KEY, patient_name VARCHAR(100), city VARCHAR(50), segment VARCHAR(30), joined_date DATE);
CREATE TABLE doctors (doctor_id INT PRIMARY KEY, doctor_name VARCHAR(100), category VARCHAR(50), status VARCHAR(30), base_value NUMERIC(14,2));
CREATE TABLE appointments (appointment_id INT PRIMARY KEY, patient_id INT REFERENCES patients(patient_id), doctor_id INT REFERENCES doctors(doctor_id), appointment_date DATE, status VARCHAR(30), bill_amount NUMERIC(14,2));
CREATE TABLE visits (visit_id INT PRIMARY KEY, appointment_id INT REFERENCES appointments(appointment_id), visit_date DATE, visit_type VARCHAR(40), quantity INT, amount NUMERIC(14,2), status VARCHAR(30));

Insurance.schema:
CREATE TABLE customers (customer_id INT PRIMARY KEY, customer_name VARCHAR(100), city VARCHAR(50), segment VARCHAR(30), joined_date DATE);
CREATE TABLE insurance_products (product_id INT PRIMARY KEY, product_name VARCHAR(100), category VARCHAR(50), status VARCHAR(30), base_value NUMERIC(14,2));
CREATE TABLE policies (policy_id INT PRIMARY KEY, customer_id INT REFERENCES customers(customer_id), product_id INT REFERENCES insurance_products(product_id), start_date DATE, status VARCHAR(30), premium_amount NUMERIC(14,2));
CREATE TABLE claims (claim_id INT PRIMARY KEY, policy_id INT REFERENCES policies(policy_id), claim_date DATE, claim_type VARCHAR(40), quantity INT, amount NUMERIC(14,2), status VARCHAR(30));

Capital Markets.schema:
CREATE TABLE investors (investor_id INT PRIMARY KEY, investor_name VARCHAR(100), city VARCHAR(50), segment VARCHAR(30), joined_date DATE);
CREATE TABLE securities (security_id INT PRIMARY KEY, security_name VARCHAR(100), category VARCHAR(50), status VARCHAR(30), base_value NUMERIC(14,2));
CREATE TABLE holdings (holding_id INT PRIMARY KEY, investor_id INT REFERENCES investors(investor_id), security_id INT REFERENCES securities(security_id), acquired_date DATE, status VARCHAR(30), market_value NUMERIC(14,2));
CREATE TABLE trades (trade_id INT PRIMARY KEY, holding_id INT REFERENCES holdings(holding_id), trade_date DATE, trade_type VARCHAR(40), quantity INT, amount NUMERIC(14,2), status VARCHAR(30));

Semiconductor.schema:
CREATE TABLE clients (client_id INT PRIMARY KEY, client_name VARCHAR(100), city VARCHAR(50), segment VARCHAR(30), joined_date DATE);
CREATE TABLE chip_products (product_id INT PRIMARY KEY, product_name VARCHAR(100), category VARCHAR(50), status VARCHAR(30), base_value NUMERIC(14,2));
CREATE TABLE production_batches (batch_id INT PRIMARY KEY, client_id INT REFERENCES clients(client_id), product_id INT REFERENCES chip_products(product_id), production_date DATE, status VARCHAR(30), batch_cost NUMERIC(14,2));
CREATE TABLE test_results (test_id INT PRIMARY KEY, batch_id INT REFERENCES production_batches(batch_id), test_date DATE, test_type VARCHAR(40), quantity INT, amount NUMERIC(14,2), status VARCHAR(30));

Education.schema:
CREATE TABLE students (student_id INT PRIMARY KEY, student_name VARCHAR(100), city VARCHAR(50), segment VARCHAR(30), joined_date DATE);
CREATE TABLE courses (course_id INT PRIMARY KEY, course_name VARCHAR(100), category VARCHAR(50), status VARCHAR(30), base_value NUMERIC(14,2));
CREATE TABLE enrollments (enrollment_id INT PRIMARY KEY, student_id INT REFERENCES students(student_id), course_id INT REFERENCES courses(course_id), enrollment_date DATE, status VARCHAR(30), course_fee NUMERIC(14,2));
CREATE TABLE assessments (assessment_id INT PRIMARY KEY, enrollment_id INT REFERENCES enrollments(enrollment_id), assessment_date DATE, assessment_type VARCHAR(40), quantity INT, amount NUMERIC(14,2), status VARCHAR(30));

Retail.schema:
CREATE TABLE customers (customer_id INT PRIMARY KEY, customer_name VARCHAR(100), city VARCHAR(50), segment VARCHAR(30), joined_date DATE);
CREATE TABLE products (product_id INT PRIMARY KEY, product_name VARCHAR(100), category VARCHAR(50), status VARCHAR(30), base_value NUMERIC(14,2));
CREATE TABLE orders (order_id INT PRIMARY KEY, customer_id INT REFERENCES customers(customer_id), product_id INT REFERENCES products(product_id), order_date DATE, status VARCHAR(30), order_total NUMERIC(14,2));
CREATE TABLE order_items (order_item_id INT PRIMARY KEY, order_id INT REFERENCES orders(order_id), item_date DATE, item_type VARCHAR(40), quantity INT, amount NUMERIC(14,2), status VARCHAR(30));
